try:
    print('>>> f = divmod')
    print('>>> x = []')
    print('>>> y = type(1)')
    print('>>> f(x, y)')
    f = divmod
    x = []
    y = type(1)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
